function validate([list]) {
  if (!Array.isArray(list) || list.length < 2 || list.length > 100000) return 'list needs 2 to 10^5 nodes.';
  if (list.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Node values are whole numbers from 0 to 10^9.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values] = input;
  const nodes = kit.listNodes(values);
  nodes[nodes.length - 1].next = nodes[0];
  const result = solve(nodes[0]);
  if (!Array.isArray(result) || result.length !== 2) throw new Error('Return an array holding the two heads.');
  // Read each returned circle once, from its head until the walk comes back to it.
  return result.map(head => {
    if (head === null || typeof head !== 'object') throw new Error('Each half must be a non-empty circular list.');
    const out = [];
    let node = head;
    do {
      if (node === null || typeof node !== 'object') throw new Error('Each half must stay circular: its last node points back to its head.');
      if (out.length >= values.length) throw new Error('Each half must close back on its own head.');
      out.push(node.val);
      node = node.next;
    } while (node !== head);
    return out;
  });
}

