function splitCircularLinkedList(list) {
  let slow = list;
  let fast = list;
  while (fast.next !== list && fast.next.next !== list) {
    slow = slow.next;
    fast = fast.next.next;
  }

  if (fast.next.next === list) {
    fast = fast.next;
  }

  const second = slow.next;
  slow.next = list;
  fast.next = second;
  return [list, second];
}

