function splitCircularLinkedList(list) {
  const nodes = [list];
  for (let node = list.next; node !== list; node = node.next) nodes.push(node);
  const cut = Math.ceil(nodes.length / 2);
  const halves = [nodes.slice(0, cut), nodes.slice(cut)];
  for (const half of halves) {
    half.forEach((node, i) => { node.next = half[(i + 1) % half.length]; });
  }
  return halves.map(half => half[0]);
}

