function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 8);
  const top = large || rand() < 0.2 ? 1000000000 : 9;
  return [Array.from({ length: n }, () => Math.floor(rand() * (top + 1)))];
}
